import static org.junit.Assert.*;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Base64;
import java.util.Locale;
import org.junit.Test;

public class StreamLoaderTest {
    private static final String[] PRIMARY = {
        "",
        "AAL0AAB7MUFZJlNZLpDh0wAAB//r+sDAAGoAgJABAACALyWcAMAAAFAAAUAEIAAAKKAAVDVPUDQAAAB4oaCVEDQaADQ0AASJKlbxlIsdrVikBaQ+SgGa9X/D7EB7gw8a1pnWnpDowEcBhCIMIKw/LVDWur9AG/i7kinChIF0hw6Y"
    };
    private static final String[] MANY = {
        "",
        ""
    };
    private static final String[] LARGE = {
        "",
        ""
    };
    private static final String[] LOCALE = {
        "AABqAABqAAIiCKpUAAAHAAAp4Kw2awAACAAAKzFBWSZTWYgLD0wAAACWAEAAKCAIACAAIYNBmgyJQ4u5IpwoSEQFh6YAMUFZJlNZ+aD2DAAAAZWAQAAAIAYAhAAgACGADAGpNVuLuSKcKEh80HsGAA==",
        "AAAlAABMMUFZJlNZlYg/7AAAAl+RUMBQAAEAKCAMAAYIhAAAFEAAIAAxTCaaA0xCIyaNGjQ9Q6QrrIibSMKw6wcDijuTD+HxdyRThQkJWIP+wA=="
    };
    private static final String[] EMPTY = {
        "AAACAAACAAA=",
        "AAACAAAhMUFZJlNZ/0ibggAAAMAAQAAgACEYRsLuSKcKEh/pE3BA"
    };

    // Independent Python struct + bz2 fixtures. No production encoder used.
    private static final int[][][] PRIMARY_STATE = {new int[][] {new int[] {-104970717, -590339743, -516999337, 2106, 2106}, new int[] {0, 7, 666, 15, 16}, new int[] {10, 42, 40, 45, 47}, new int[] {58, 68, 110, 150, 195}},
        new int[][] {new int[] {-104970717, -590339743, -516999337, 2106, 2106}, new int[] {0, 7, 666, 15, 16}, new int[] {0, 7, 666, 15, 16}, new int[] {52, 52, 59, 725, 740}}};

    @Test public void bothCompressionLayoutsDecodeDistinctFilesAndReturnFreshStorage() throws Exception {
        Locale previous = Locale.getDefault();
        try {
            Locale.setDefault(Locale.US);
            for (int mode = 0; mode < 2; mode++) {
                byte[] encoded = decode(PRIMARY[mode]);
                byte[] before = encoded.clone();
                StreamLoader loader = new StreamLoader(encoded);
                byte[] alpha = {0, 1, 127, (byte)128, (byte)255, 3, 0};
                assertArrayEquals(new byte[0], loader.getDataForName("zero.dat"));
                assertArrayEquals(alpha, loader.getDataForName("alpha.dat"));
                assertArrayEquals(alpha, loader.getDataForName("AlPhA.DaT"));
                byte[] beta = new byte[666]; Arrays.fill(beta, (byte)37);
                assertArrayEquals(beta, loader.getDataForName("BETA.DAT"));
                assertNull(loader.getDataForName("MISSING.DAT"));
                assertNull(loader.getDataForName("ALPHA"));
                byte[] first = loader.getDataForName("ALPHA.DAT");
                first[0] = 88;
                assertArrayEquals(alpha, loader.getDataForName("alpha.dat"));
                assertNotSame(first, loader.getDataForName("alpha.dat"));
                assertArrayEquals(before, encoded);
                assertEquals(5, state(loader, "dataSize", "entryCount"));
                assertEquals(mode == 1, state(loader, "aBoolean732", "archiveDecompressed"));
                String[][] fields = {{"anIntArray728", "entryNameHashes"}, {"anIntArray729", "entryUnpackedSizes"},
                        {"anIntArray730", "entryPackedSizes"}, {"anIntArray731", "entryOffsets"}};
                for (int i = 0; i < fields.length; i++)
                    assertArrayEquals(PRIMARY_STATE[mode][i], (int[])state(loader, fields[i][0], fields[i][1]));
                byte[] backing = (byte[]) state(loader, "aByteArray726", "archiveData");
                if (mode == 0) assertSame(encoded, backing);
                else {
                    assertNotSame(encoded, backing);
                    assertEquals((encoded[0]&255)*65536+(encoded[1]&255)*256+(encoded[2]&255), backing.length);
                    assertEquals(0, backing[0]); assertEquals(5, backing[1]);
                }
            }
        } finally { Locale.setDefault(previous); }
    }

    @Test public void lookupUsesFirstMatchingHashRatherThanFullNameEquality() {
        for (String fixture : PRIMARY) {
            StreamLoader loader = new StreamLoader(decode(fixture));
            byte[] first = "first collision".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
            assertArrayEquals(first, loader.getDataForName("A}"));
            assertArrayEquals(first, loader.getDataForName("B@"));
            assertNull(loader.getDataForName("B}"));
        }
    }

    @Test public void unsignedEntryCountAndCumulativeOffsetsReachEveryMember() throws Exception {
        for (String fixture : MANY) {
            StreamLoader loader = new StreamLoader(decode(fixture));
            assertEquals(257, state(loader, "dataSize", "entryCount"));
            for (int i = 256; i >= 0; i--) {
                assertArrayEquals(new byte[] {(byte)i, (byte)(255-i)}, loader.getDataForName(String.format(Locale.US, "E%03d", i)));
            }
            assertNull(loader.getDataForName("E257"));
        }
    }

    @Test public void threeByteLengthsPreservePayloadBeyondUnsignedWordBoundary() throws Exception {
        byte[] expected = new byte[69893];
        for (int i = 0; i < 69888; i++) expected[i] = (byte)i;
        byte[] tail = {0, (byte)128, (byte)255, 127, 17};
        System.arraycopy(tail, 0, expected, 69888, tail.length);
        for (String fixture : LARGE) {
            StreamLoader loader = new StreamLoader(decode(fixture));
            assertArrayEquals(expected, loader.getDataForName("large.dat"));
            assertArrayEquals(new int[] {69893}, (int[])state(loader, "anIntArray729", "entryUnpackedSizes"));
            assertNull(loader.getDataForName("large.da"));
        }
    }

    @Test public void nameUppercasingRetainsDefaultLocaleDependency() {
        Locale previous = Locale.getDefault();
        try {
            for (String fixture : LOCALE) {
                StreamLoader loader = new StreamLoader(decode(fixture));
                Locale.setDefault(Locale.US);
                assertArrayEquals("ASCII I".getBytes(java.nio.charset.StandardCharsets.US_ASCII), loader.getDataForName("i.dat"));
                Locale.setDefault(new Locale("tr", "TR"));
                assertArrayEquals("dotted I".getBytes(java.nio.charset.StandardCharsets.US_ASCII), loader.getDataForName("i.dat"));
                assertArrayEquals("ASCII I".getBytes(java.nio.charset.StandardCharsets.US_ASCII), loader.getDataForName("I.DAT"));
            }
        } finally { Locale.setDefault(previous); }
    }

    @Test public void emptyTablesAndEmptyPayloadsAreDifferentFromMissingFiles() throws Exception {
        for (String fixture : EMPTY) {
            StreamLoader loader = new StreamLoader(decode(fixture));
            assertEquals(0, state(loader, "dataSize", "entryCount"));
            assertNull(loader.getDataForName("ZERO.DAT"));
        }
        for (String fixture : PRIMARY)
            assertArrayEquals(new byte[0], new StreamLoader(decode(fixture)).getDataForName("ZERO.DAT"));
    }


    @Test public void unsignedShortCountBoundaryStillFindsLastEntry() throws Exception {
        String[] fixtures = {"BQADAABCMUFZJlNZF9gsigAKDcBu4IBAAAgAAAgAAIABAIggAFCAGAUqmmmj1MIE3qQJzelQJnvefZyQJ+LuSKcKEgL7BZFA", "Cf/5AABBMUFZJlNZQ89z+gAZH0Au4IAIAAAIAACAASAIoABQgBgFKpo009T6IEzSQJ75oUCZrOZtIE5n4u5IpwoSCHnuf0A="};
        int[] counts = {32768, 65535};
        for (int i = 0; i < counts.length; i++) {
            StreamLoader loader = new StreamLoader(decode(fixtures[i]));
            assertEquals(counts[i], state(loader, "dataSize", "entryCount"));
            assertArrayEquals(new byte[] {(byte)0x93}, loader.getDataForName("LAST.DAT"));
            assertNull(loader.getDataForName("LAST.DA"));
        }
    }

    private static byte[] decode(String fixture) { return Base64.getDecoder().decode(fixture); }

    // Assert data meaning on both versions; names themselves are never an oracle.
    private static Object state(StreamLoader loader, String original, String renamed) throws Exception {
        Field field;
        try { field = StreamLoader.class.getDeclaredField(original); }
        catch (NoSuchFieldException changed) { field = StreamLoader.class.getDeclaredField(renamed); }
        field.setAccessible(true); return field.get(loader);
    }
}
